 "content": "def transform(grid):
    # Recolor every copy of a shape to the color of the isolated example shape.
    # Demos: a compact pattern on background is replicated as a different-colored
    # pattern, while a long connected line/object serves as the color key.
    h,w=len(grid),len(grid[0]); flat=[v for row in grid for v in row]
    bg=max(set(flat),key=flat.count)
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       v=grid[r][c]
       if v==bg or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); cells=[]
       while st:
        x,y=st.pop(); cells.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         a,b=x+dx,y+dy
         if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==v:
          seen.add((a,b)); st.append((a,b))
       comps.append((v,cells))
    def shape(cs):
      a=min(x for x,y in cs); b=min(y for x,y in cs)
      return frozenset((x-a,y-b) for x,y in cs)
    # identify uniquely-shaped small motifs and their color, then recolor larger copies
    motifs={}
    for v,cs in comps:
      motifs.setdefault(shape(cs),[]).append((v,cs))
    out=[row[:] for row in grid]
    for shp,items in motifs.items():
      # Single occurrence of a motif is the color reference; occurrences with same geometry
      # remain unless a larger-colored duplicate is present.
      colors=[v for v,cs in items]
      if len(set(colors))<2: continue
      ref=next((v for v,cs in items if len(cs)<min(len(z) for _,z in items)),None)
      if ref is None: continue
      for v,cs in items:
       if v!=ref:
        for x,y in cs: out[x][y]=ref
    # In these tasks the recolored object is a repeated copy of an isolated 3xN motif;
    # use same shape matching across components regardless of area.
    return out
